/** Additional checks execute the production functions in the browser. */
function runAdditionalChecks() {
  const checks=[];
  const assert=(condition,message)=>{if(!condition)throw new Error(message);};
  const check=(name,expected,fn)=>{
    try {checks.push({name,expected,observed:fn(),status:'PASS'});}
    catch(e){checks.push({name,expected,status:'FAIL',error:String(e.stack||e)});}
  };
  const vector=r=>({...r,p:Array.from(r.p)});
  check('Directed fixture vectors, one-step orientation and extra update','vector error <1e-6, stationary extra L1 <1e-6',()=>{
    const t=REFERENCE_GRAPH.transition;
    const a=pageRank(.85,{transition:t}), b=personalizedPageRank(0,.85,{transition:t});
    const first=pageRank(.85,{transition:t,maxIter:1});
    const expected=[.25,.14375,.56875,.0375];
    assert(first.p.every((x,i)=>Math.abs(x-expected[i])<1e-7),'one-step mismatch');
    const rows=[a,b].map((r,k)=>{
      const v=k ? [1,0,0,0] : [.25,.25,.25,.25];
      const next=hw6Step(.85,t,v,r.p), l1=next.reduce((s,x,i)=>s+Math.abs(x-r.p[i]),0);
      assert(l1<1e-6 && r.maxMassError<2e-6 && r.minProbability>=0,'invariant failed');
      return {...vector(r),extraUpdateL1:l1,expected:REFERENCE_GRAPH.reference[k?'restartAtA':'uniform'].p};
    });
    return {firstStep:vector(first),stationary:rows};
  });
  check('Independent directed dangling fixture','uniform stationary [0.350877193,0.649122807]; seed 1 stays dangling',()=>{
